function handleCheckInventory(eventData)
{
   SHELL.removeListener(SHELL.CHECK_INVENTORY,handleCheckInventory,this);
   if(INTERFACE.getActivePlayerId() != eventData.playerID)
   {
      return undefined;
   }
   if(featherItemID != eventData.itemID)
   {
      return undefined;
   }
   if(eventData.isOwned)
   {
      this.gotoAndStop(HAS_FEATHER_FRAME_LABEL);
   }
   else
   {
      this.gotoAndStop(NO_FEATHER_FRAME_LABEL);
   }
}
function handlePlayerCardClosed()
{
   INTERFACE.removeEventListener(INTERFACE.PLAYER_CARD_CLOSED,handlePlayerCardClosed,this);
   INTERFACE.removeEventListener(INTERFACE.PLAYER_CARD_UPDATED,handlePlayerCardUpdated,this);
}
function handlePlayerCardUpdated()
{
   var _loc2_ = INTERFACE.getActivePlayerObject();
   if(_loc2_.player_id == SHELL.getMyPlayerId())
   {
      SHELL.addListener(SHELL.CHECK_INVENTORY,handleCheckInventory,this);
      SHELL.sendCheckInventory(featherItemID,_loc2_.player_id);
   }
}
stop();
var HAS_FEATHER_FRAME_LABEL = "feather";
var NO_FEATHER_FRAME_LABEL = "noFeather";
var featherItemID = 7036;
var INTERFACE = _global.getCurrentInterface();
var SHELL = _global.getCurrentShell();
if(SHELL.getState() == SHELL.PLAY_STATE)
{
   var activePlayer = INTERFACE.getActivePlayerObject();
   SHELL.addListener(SHELL.CHECK_INVENTORY,handleCheckInventory,this);
   SHELL.sendCheckInventory(featherItemID,activePlayer.player_id);
   INTERFACE.addEventListener(INTERFACE.PLAYER_CARD_CLOSED,handlePlayerCardClosed,this);
   INTERFACE.addEventListener(INTERFACE.PLAYER_CARD_UPDATED,handlePlayerCardUpdated,this);
}
